INSERT INTO "presets" ("id", "label", "prompt", "is_bakeoff_safe", "sort_order") VALUES
	('shoulder-sequence', 'Shoulder Sequence', 'The camera starts on a close-up of the garment detail at the shoulder and waist, then pulls back to reveal the model posing in the full outfit. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 10),
	('turn-around', 'Turn Around', 'The model slowly turns around on the spot to show the back of the outfit while the camera circles gently with them. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 11),
	('effortless-flip', 'Effortless Flip', 'The model flips their hair with a relaxed head toss, then settles and faces the camera as the camera eases back to a full-body shot. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 12),
	('studio-poise', 'Studio Pose', 'In a clean studio, the model shifts weight, touches the collar and settles into a confident pose with a slight smile; the camera stays almost still. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 13),
	('arc-right', 'Arc Right', 'The camera arcs smoothly to the right around the standing model, moving from a front view towards a side and back view of the outfit. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 14),
	('arc-left', 'Arc Left', 'The camera arcs smoothly to the left around the standing model, moving from a front view towards a side and back view of the outfit. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 15),
	('smile-pose', 'Smile & Pose', 'The model turns from a side angle to face the camera, smiles and settles into a relaxed pose with one hand on the hip. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 16),
	('step-back', 'Step Back', 'The model takes a small, relaxed step back while the camera pulls back slightly, ending on a full-body shot of the outfit. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 17),
	('the-approach', 'The Approach', 'The camera slowly pushes in from a full-body shot to a close-up of the face and upper outfit while the model holds a calm gaze. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 18),
	('head-to-toe-shot', 'Head-to-Toe Shot', 'The camera starts low on the shoes and tilts up along the outfit to the face, ending on a full-body shot of the model. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 19),
	('walk-right', 'Walk Right', 'The model walks naturally across the frame to the right while the camera tracks alongside at the same pace. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 20),
	('walk-left', 'Walk Left', 'The model walks naturally across the frame to the left while the camera tracks alongside at the same pace. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 21),
	('minimal-motion', 'Minimal Motion', 'The model stands almost still, with subtle breathing, a small shift of weight and a slow blink; the camera holds steady. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 22),
	('doberman-gaze', 'Doberman Gaze', 'The model stands still in a bold setting and slowly turns their gaze to the camera; a static camera with very subtle movement. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 23),
	('runway-walk', 'Runway Walk', 'The model walks straight towards the camera with a confident runway stride; the camera holds its position and keeps the full outfit in frame. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 24),
	('face-rush', 'Face Rush', 'The camera rushes in from a wide shot to a close-up of the face, then swings around the model to show the outfit from the side and back. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 25),
	('outfit-check', 'Outfit Check', 'A quick outfit check: the full look, then close-ups of the jacket, skirt and accessories, then the model turns to show the back. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 26),
	('outfit-reveal', 'Outfit Reveal', 'A hand moves away from the lens to reveal the model in the full outfit, then the camera glides over fabric details and ends on a pose. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 27),
	('golden-hour-wall', 'Golden Hour Wall', 'The model walks out of the shadow into warm golden-hour light and leans against a sunlit wall, as the camera follows smoothly. Keep the person, their face, the outfit, its colours and any printed text exactly as in the image. Do not add any text, logos or watermarks. Smooth, stable camera.', false, 28)
